def revenue(units, price):
    return units * price


def growth(a, b):
    # returns percent change from a to b
    if a == 0:
        # Avoid division by zero; define growth from zero as infinite if b != 0, else 0
        return float('inf') if b != 0 else 0.0
    return (b - a) / a
